style.css:
@-moz-document domain("mixcloud.com") {
/* Native dark theme tokens: stronger crimson, scarlet hover, translucent surfaces. */
  :root {
    --color-core-primary: #E8112D !important;
    --color-core-primary-hover: #FF3045 !important;
    --color-core-brand: #FF1837 !important;
    --color-core-pro: #F21D38 !important;
    --color-core-important: #E8112D !important;
    --color-core-important-hover: #FF3045 !important;
    --color-text-link: #FF4252 !important;
    --color-text-link-hover: #FF6B6F !important;
    --color-text-hover: #FF6B6F !important;
    --color-text-fixed-highlight: #FF4252 !important;

    --color-surface-primary: rgba(11, 6, 15, 0.59) !important;
    --color-surface-primary-hover: rgba(67, 10, 25, 0.66) !important;
    --color-surface-secondary: rgba(15, 7, 18, 0.68) !important;
    --color-surface-secondary-hover: rgba(80, 12, 30, 0.72) !important;
    --color-surface-tertiary: rgba(20, 9, 24, 0.73) !important;
    --color-surface-tertiary-hover: rgba(86, 13, 32, 0.76) !important;
    --color-surface-subtle: rgba(20, 9, 24, 0.56) !important;
    --color-surface-subtle-hover: rgba(84, 11, 28, 0.63) !important;
    --color-surface-raised: rgba(20, 8, 22, 0.80) !important;
    --color-surface-fixed: rgba(16, 7, 18, 0.75) !important;
    --color-surface-fixed-raised: rgba(20, 8, 22, 0.84) !important;
    --color-surface-fixed-hover: rgba(84, 11, 28, 0.79) !important;
    --color-surface-cta: #E8112D !important;
    --color-surface-cta-hover: #FF3045 !important;
    --color-border-secondary: #87223A !important;

    /* Native player waveform: BRIGHT RED played and dark-red unplayed. */
    --color-waveform-active-default: #FF1636 !important;
    --color-waveform-active-listened: #FF3346 !important;
    --color-waveform-active-interacted: #FF4A55 !important;
    --color-waveform-initial-default: #4D1929 !important;
    --color-waveform-initial-listened: #762438 !important;
    --color-waveform-initial-interacted: #96324A !important;
    --rgb-surface-primary: 11, 6, 15 !important;
  }

  /* Exact Mixcloud StyleX token aliases from the earlier working theme.
     These preserve the native waveform rendering instead of drawing a fake bar. */
  :root,
  :root .xe156bp,
  :root .x10zkq2b,
  :root .x1vim7mw,
  :root .x1z08qlr {
    --x3szyx3: #E8112D !important;
    --x1tespoo: #FF3045 !important;
    --xncjjcy: #FF1837 !important;
    --x1yvspgp: #F21D38 !important;
    --x1towjpp: #E8112D !important;
    --xiimk2m: #FF3045 !important;
    --xci8cdj: #FF4252 !important;
    --xvwwwoo: #FF6B6F !important;
    --x17dosfj: #FF6B6F !important;
    --x7ayvfl: #FF4252 !important;
    --xoyu9nr: rgba(11, 6, 15, 0.59) !important;
    --x1wj7fr6: rgba(67, 10, 25, 0.66) !important;
    --x1p995gz: rgba(15, 7, 18, 0.68) !important;
    --xrtexq9: rgba(80, 12, 30, 0.72) !important;
    --xas8k3g: rgba(20, 9, 24, 0.73) !important;
    --x1gs6i04: rgba(86, 13, 32, 0.76) !important;
    --xwjt3o7: rgba(20, 9, 24, 0.56) !important;
    --xyv7w3a: rgba(84, 11, 28, 0.63) !important;
    --xa35n7o: rgba(20, 8, 22, 0.80) !important;
    --x1ua1qzq: rgba(16, 7, 18, 0.75) !important;
    --x171k3he: rgba(84, 11, 28, 0.79) !important;
    --xtpxhup: rgba(20, 8, 22, 0.84) !important;
    --x1qa8ivo: #E8112D !important;
    --x17jy07m: #FF3045 !important;
    --x1mlrjow: #87223A !important;
    --x73uu39: #FF1636 !important;
    --xvgdhl7: #FF3346 !important;
    --x1msfqiw: #FF4A55 !important;
    --xgbvqa9: #4D1929 !important;
    --x1jwdph4: #762438 !important;
    --xjutsup: #96324A !important;
  }

  /* Make page content, discovery/library sections and cards reveal wallpaper. */
  main,
  [role="main"] {
    background-color: transparent !important;
  }
  main [data-sentry-component="Card"],
  main [data-sentry-component="CloudcastCard"],
  main [data-sentry-component="PlaylistCard"],
  main [data-sentry-component="FeedCard"],
  main [data-sentry-component="Container"],
  [role="main"] [data-sentry-component="Card"] {
    background-color: rgba(13, 7, 17, 0.60) !important;
    border-color: rgba(196, 47, 70, 0.23) !important;
  }

  /* Transparent left/right menus and the top navigation in Dark mode. */
  header,
  [role="banner"],
  [data-sentry-component="TopNav"] {
    background-color: rgba(11, 5, 15, 0.76) !important;
    border-color: #612031 !important;
  }
  aside,
  nav[aria-label],
  [role="navigation"] {
    background-color: rgba(13, 6, 17, 0.55) !important;
  }

  /* Popover/menu surfaces stay translucent but readable. */
  [role="menu"],
  [role="listbox"],
  [role="dialog"],
  [role="tooltip"],
  dialog,
  [popover],
  .react-datepicker,
  .react-datepicker__header {
    background-color: rgba(17, 7, 20, 0.87) !important;
    color: #FBECEF !important;
    border-color: #86263B !important;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.52) !important;
  }
  [role="menu"] > div,
  [role="listbox"] > div,
  [role="dialog"] > div,
  [role="menu"] > ul,
  [role="listbox"] > ul {
    background-color: rgba(17, 7, 20, 0.47) !important;
  }

  /* Red glow hover and selected states. Keep normal buttons native. */
  a:hover,
  a:focus,
  nav a:hover,
  [role="menuitem"]:hover,
  [role="option"]:hover {
    color: #FF6B6F !important;
  }
  button:hover,
  [role="button"]:hover,
  [data-sentry-component="Button"]:hover {
    background-color: rgba(203, 16, 43, 0.36) !important;
    border-color: #FF3045 !important;
    box-shadow: 0 0 12px rgba(255, 32, 64, 0.21) !important;
  }
  [role="menu"] a:hover,
  [role="menu"] button:hover,
  [role="listbox"] [role="option"]:hover,
  [role="menuitem"][data-highlighted],
  [role="option"][data-highlighted] {
    background-color: rgba(195, 12, 39, 0.34) !important;
    color: #FF6B6F !important;
  }
  a[aria-current="page"],
  [role="tab"][aria-selected="true"],
  button[aria-pressed="true"] {
    color: #FF4658 !important;
    border-color: #FF3045 !important;
  }
  ::selection {
    background: #A2102E !important;
    color: #FFFFFF !important;
  }
  input[type="checkbox"],
  input[type="radio"],
  input[type="range"] {
    accent-color: #FF3045 !important;
  }

  /* Waveforms in the bottom fixed player AND track players on artist pages. */
  [data-sentry-component="WaveformRenderer"],
  [data-sentry-element="WaveformRenderer"],
  svg[data-sentry-component="WaveformRenderer"],
  [data-testid="waveform"] {
    --color-waveform-active-default: #FF1636 !important;
    --color-waveform-active-listened: #FF3346 !important;
    --color-waveform-active-interacted: #FF4A55 !important;
    --color-waveform-initial-default: #4D1929 !important;
    --color-waveform-initial-listened: #762438 !important;
    --color-waveform-initial-interacted: #96324A !important;
    --x73uu39: #FF1636 !important;
    --xvgdhl7: #FF3346 !important;
    --x1msfqiw: #FF4A55 !important;
    --xgbvqa9: #4D1929 !important;
    --x1jwdph4: #762438 !important;
    --xjutsup: #96324A !important;
  }
  /* When Mixcloud renders progress as an HTML meter/slider. */
  progress {
    color: #FF263D !important;
    accent-color: #FF263D !important;
  }
  progress::-webkit-progress-value {
    background-color: #FF263D !important;
  }
  progress::-webkit-progress-bar {
    background-color: #4D1929 !important;
  }
  progress::-moz-progress-bar {
    background-color: #FF263D !important;
  }
  input[type="range"] {
    accent-color: #FF263D !important;
  }

  svg[data-sentry-element="MixcloudLogo"],
  svg[data-sentry-component="LogoMedium"] {
    color: #FF2641 !important;
    fill: currentColor !important;
  }
  h1 {
    font-family: "Old English Text MT", "Blackadder ITC", Georgia, serif !important;
  }
  h2, h3 {
    font-family: "Cinzel Decorative", "Palatino Linotype", Georgia, serif !important;
  }
  h4, h5, h6, nav a, [role="tab"] {
    font-family: "Cinzel", "Palatino Linotype", Georgia, serif !important;
  }
  html, body, button, input, textarea, select {
    color-scheme: dark;
  }



  /* V5 red glow styling: logo, text, side menu and album-art hover effects. */
  svg[data-sentry-element="MixcloudLogo"],
  svg[data-sentry-component="LogoMedium"],
  a[href="/"] svg {
    color: #FF2946 !important;
    fill: currentColor !important;
    filter: drop-shadow(0 0 6px rgba(255, 35, 70, 0.92)) drop-shadow(0 0 14px rgba(255, 20, 55, 0.72)) !important;
  }
  a[href="/"]:hover svg,
  a[href="/"]:focus svg,
  [data-sentry-component="TopNav"] a:hover svg {
    color: #FF4A62 !important;
    fill: currentColor !important;
    filter: drop-shadow(0 0 8px rgba(255, 52, 86, 0.98)) drop-shadow(0 0 18px rgba(255, 34, 70, 0.82)) !important;
  }

  body,
  main,
  aside,
  nav,
  header,
  p,
  span,
  div,
  li,
  label,
  small,
  strong,
  em,
  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  button,
  a,
  [role="button"],
  [role="menuitem"],
  [role="tab"],
  [role="option"] {
    color: #FF6F7F !important;
  }
  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  main a,
  main strong,
  main [data-sentry-component="CloudcastCard"] a,
  main [data-sentry-component="PlaylistCard"] a {
    color: #FF8490 !important;
    text-shadow: 0 0 6px rgba(120, 8, 28, 0.18) !important;
  }
  small,
  time,
  [data-sentry-component="TopNav"] small,
  [data-sentry-component="TopNav"] span {
    color: #FF5568 !important;
  }

  aside a,
  nav[aria-label] a,
  [role="navigation"] a,
  aside button,
  nav[aria-label] button,
  [role="navigation"] button {
    border-radius: 10px !important;
    transition: box-shadow 0.18s ease, background-color 0.18s ease, color 0.18s ease !important;
  }
  aside a:hover,
  aside a:focus,
  nav[aria-label] a:hover,
  nav[aria-label] a:focus,
  [role="navigation"] a:hover,
  [role="navigation"] a:focus,
  aside button:hover,
  aside button:focus,
  nav[aria-label] button:hover,
  nav[aria-label] button:focus,
  [role="navigation"] button:hover,
  [role="navigation"] button:focus {
    color: #FF8B96 !important;
    background-color: rgba(175, 16, 42, 0.22) !important;
    box-shadow: 0 0 14px rgba(255, 38, 72, 0.40), inset 0 0 0 1px rgba(255, 58, 88, 0.52) !important;
    text-shadow: 0 0 8px rgba(255, 54, 84, 0.42) !important;
  }

  main [data-sentry-component="CloudcastCard"] img,
  main [data-sentry-component="PlaylistCard"] img,
  main [data-sentry-component="Card"] img,
  main [data-sentry-component="CloudcastCard"] picture img,
  main [data-sentry-component="PlaylistCard"] picture img,
  main [data-sentry-component="Card"] picture img {
    border: 1px solid rgba(190, 35, 60, 0.18) !important;
    box-shadow: 0 0 0 rgba(0, 0, 0, 0) !important;
    transition: box-shadow 0.18s ease, border-color 0.18s ease, transform 0.18s ease !important;
  }
  main [data-sentry-component="CloudcastCard"]:hover img,
  main [data-sentry-component="PlaylistCard"]:hover img,
  main [data-sentry-component="Card"]:hover img,
  main [data-sentry-component="CloudcastCard"] a:hover img,
  main [data-sentry-component="PlaylistCard"] a:hover img,
  main [data-sentry-component="Card"] a:hover img {
    border-color: #FF4360 !important;
    box-shadow: 0 0 18px rgba(255, 34, 70, 0.45), 0 0 28px rgba(255, 34, 70, 0.22) !important;
    transform: translateY(-1px) !important;
  }

  /* Embedded thumbnail-derived castle wallpaper (no external host). */
  body {
    background-color: #09070D !important;
    background-image: url("data:image/jpeg;base64,") !important;
    background-position: center center !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
  }


  /* V6 HOVER FIX (retained): direct Mixcloud sidebar destinations plus structural fallbacks.
     StyleX-based navigation can be generic div/a elements, not nav or aside.
     Give the actual clickable tile a visible crimson border and outer glow. */
  body a[href="/"]:hover,
  body a[href^="/live"]:hover,
  body a[href^="/genres"]:hover,
  body a[href^="/discover"]:hover,
  body a[href^="/library"]:hover,
  body a[href^="/community"]:hover,
  body a[href^="/trending"]:hover,
  body a[href="/premium/"]:hover,
  body a[href="/premium-for-listeners/"]:hover,
  body nav a:hover,
  body aside a:hover,
  body [role="navigation"] a:hover,
  body [data-sentry-component*="Sidebar"] a:hover,
  body [data-sentry-component*="SideNav"] a:hover,
  body [data-testid*="sidebar"] a:hover,
  body [data-testid*="side-nav"] a:hover {
    background: rgba(239, 20, 53, 0.29) !important;
    color: #FFAFB7 !important;
    border-radius: 10px !important;
    outline: 1px solid rgba(255, 74, 96, 0.82) !important;
    outline-offset: -1px !important;
    box-shadow: 0 0 0 1px rgba(255, 34, 64, 0.30),
                0 0 16px rgba(255, 19, 52, 0.80),
                0 0 30px rgba(255, 19, 52, 0.28) !important;
  }

  /* Highlight label + icon as well as the clickable sidebar tile.
     V5 forces span/div colors globally, so descendants need a stronger override. */
  body a[href="/"]:hover span,
  body a[href^="/live"]:hover span,
  body a[href^="/genres"]:hover span,
  body a[href^="/discover"]:hover span,
  body a[href^="/library"]:hover span,
  body a[href^="/community"]:hover span,
  body a[href^="/trending"]:hover span,
  body nav a:hover span,
  body aside a:hover span,
  body [role="navigation"] a:hover span,
  body nav a:hover div,
  body aside a:hover div,
  body [role="navigation"] a:hover div {
    color: #FFAFB7 !important;
    text-shadow: 0 0 8px rgba(255, 30, 60, 0.82) !important;
  }
  body a[href="/"]:hover svg,
  body a[href^="/live"]:hover svg,
  body a[href^="/genres"]:hover svg,
  body a[href^="/discover"]:hover svg,
  body a[href^="/library"]:hover svg,
  body a[href^="/community"]:hover svg,
  body a[href^="/trending"]:hover svg,
  body nav a:hover svg,
  body aside a:hover svg,
  body [role="navigation"] a:hover svg {
    color: #FF435B !important;
    filter: drop-shadow(0 0 5px rgba(255, 24, 56, 0.98))
            drop-shadow(0 0 11px rgba(255, 24, 56, 0.68)) !important;
  }
  body nav button:hover,
  body aside button:hover,
  body [role="navigation"] button:hover,
  body [role="navigation"] [role="button"]:hover {
    background: rgba(239, 20, 53, 0.29) !important;
    outline: 1px solid rgba(255, 74, 96, 0.82) !important;
    border-radius: 10px !important;
    box-shadow: 0 0 16px rgba(255, 19, 52, 0.75) !important;
  }

  /* If the link contains its own StyleX surface, tint that child too. */
  body a[href="/"]:hover > div,
  body a[href^="/live"]:hover > div,
  body a[href^="/genres"]:hover > div,
  body a[href^="/discover"]:hover > div,
  body a[href^="/library"]:hover > div,
  body a[href^="/community"]:hover > div,
  body nav a:hover > div,
  body aside a:hover > div {
    background-color: rgba(239, 20, 53, 0.18) !important;
    border-radius: 10px !important;
    box-shadow: inset 0 0 0 1px rgba(255, 46, 74, 0.58),
                0 0 12px rgba(255, 21, 53, 0.38) !important;
  }

  /* V6 ALBUM ART HOVER: V5 depended on Card/CloudcastCard/PlaylistCard,
     but actual image links may be plain anchors and StyleX wrappers.
     Target real images and their hovered parent anchors directly. */
  body main a:hover img,
  body [role="main"] a:hover img,
  body main img:hover,
  body [role="main"] img:hover,
  body a:hover picture img,
  body picture:hover img,
  body img:hover,
  body [data-sentry-component*="Card"]:hover img {
    outline: 2px solid #FF344F !important;
    outline-offset: -2px !important;
    box-shadow: 0 0 0 2px rgba(255, 52, 79, 0.70),
                0 0 16px rgba(255, 17, 51, 0.85),
                0 0 32px rgba(255, 12, 50, 0.43) !important;
    filter: drop-shadow(0 0 8px rgba(255, 23, 54, 0.65)) !important;
  }

  /* Background-image tiles may not contain an <img> element. */
  body main a:hover [style*="background-image"],
  body [role="main"] a:hover [style*="background-image"],
  body main [style*="background-image"]:hover,
  body [role="main"] [style*="background-image"]:hover,
  body [data-sentry-component*="Card"]:hover [style*="background-image"] {
    outline: 2px solid #FF344F !important;
    outline-offset: -2px !important;
    box-shadow: 0 0 0 2px rgba(255, 52, 79, 0.70),
                0 0 18px rgba(255, 17, 51, 0.85),
                0 0 32px rgba(255, 12, 50, 0.45) !important;
  }

  /* Glow the album artwork wrapper as well, for clipped/rounded album images. */
  body main a:hover picture,
  body [role="main"] a:hover picture,
  body main a:hover > div:first-child,
  body [role="main"] a:hover > div:first-child {
    box-shadow: 0 0 0 1px rgba(255, 44, 72, 0.46),
                0 0 20px rgba(255, 19, 52, 0.48) !important;
    border-radius: 8px !important;
  }



  /* V7: Artist/show page transparency.
     Mixcloud uses the inline --x-backgroundColor property on the player hero
     and on the eight-class colored horizontal strip.  These exact selectors
     override that inline property without changing album artwork or waves. */

  [data-testid="playerHero"] {
    --x-backgroundColor: rgba(11, 6, 15, 0.18) !important;
    background-color: rgba(11, 6, 15, 0.18) !important;
    background-image: none !important;
  }

  [data-testid="playerHero"] > [data-sentry-component="Container"] {
    background-color: rgba(11, 6, 15, 0.18) !important;
    background-image: none !important;
  }

  /* The exact eight-class strip supplied from the artist page. */
  div.x1tl5iq1.x1s85apg.x10l6tqk.xlxyqfn.x15hz3v3.x1nzwzoj.xn9wirt.xl8spv7 {
    --x-backgroundColor: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
  }

  /* Keep the waveform container transparent; leave SVG strokes, fills,
     gradients and the red play-progress colors under native player control. */
  [data-testid="playerHero"] [data-testid="waveForm"],
  [data-testid="playerHero"] [data-sentry-component="HeroWaveform"],
  [data-testid="playerHero"] [data-sentry-component="Waveform"],
  [data-testid="playerHero"] [data-sentry-component="WaveformPath"],
  [data-testid="playerHero"] [data-sentry-component="WaveformRenderer"] {
    background-color: transparent !important;
    background-image: none !important;
  }



  /* V8: Actual Mixcloud artist/show waveform uses SVG ProgressGradient stops.
     The first stop inherited white from --color-text-tertiary.
     Recolor the played portion red while keeping the unplayed part dark red.
     Do not replace the native SVG path or progress calculations. */
  [data-testid="waveForm"] {
    --color-text-tertiary: #FF2949 !important;
    --color-surface-subtle-hover: #7A1B32 !important;
    --color-surface-subtle: #451524 !important;
  }
  [data-testid="waveForm"] [data-sentry-component="ProgressGradient"] stop {
    stop-color: #591629 !important;
  }
  [data-testid="waveForm"] [data-sentry-component="ProgressGradient"] stop:first-child {
    stop-color: #FF2949 !important;
  }
}
